function estimateFlightHours(km,aircraftName){const idx=aircraft.findIndex(a=>a[0]===aircraftName);const speed=cruiseSpeedsKmh[idx>=0?idx:0]||800;return (Number(km)*1.08)/speed}
function formatFlightTime(hours){const mins=Math.max(0,Math.round(Number(hours||0)*60));return Math.floor(mins/60)+" h "+String(mins%60).padStart(2,"0")+" min"}
