function getFlightHistory(){try{return JSON.parse(localStorage.getItem(flightStoreKey)||"[]")}catch(e){return []}}
function updatePilotLevel(hours){const levels=[{hours:0,name:"دانشجوی پرواز"},{hours:50,name:"خلبان فوق‌سبک"},{hours:100,name:"خلبان هواپیمای سبک"},{hours:500,name:"کمک‌خلبان"},{hours:1000,name:"کاپیتان"}];let current=levels[0],next=null;for(let i=0;i<levels.length;i++){if(hours>=levels[i].hours)current=levels[i];else{next=levels[i];break}}const name=document.querySelector("#pilotLevel"),detail=document.querySelector("#pilotLevelDetail"),bar=document.querySelector("#pilotLevelBar");if(!name||!detail||!bar)return;name.textContent=current.name;if(next){const span=next.hours-current.hours,progress=Math.max(0,Math.min(100,((hours-current.hours)/span)*100));detail.textContent="تا "+next.name+": "+Math.max(0,(next.hours-hours).toFixed(1))+" ساعت باقی مانده";bar.style.width=progress+"%"}else{detail.textContent="بالاترین لول ثبت‌شده · 1000+ ساعت";bar.style.width="100%"}}
