function drawFlightHistory(){const history=getFlightHistory();flightHistoryHost.innerHTML="";const totalHours=history.reduce((sum,f)=>sum+(Number(f.hours)||estimateFlightHours(f.km,f.aircraft)),0);totalAirTime.textContent=formatFlightTime(totalHours);flightCount.textContent=String(history.length);updatePilotLevel(totalHours);drawFlightRatings(history,totalHours);if(!history.length){flightHistoryHost.textContent="هنوز پروازی ثبت نکرده‌ای.";return}const title=document.createElement("h3");title.textContent="سابقه پروازها";flightHistoryHost.append(title);history.slice().reverse().forEach((f,idx)=>{const row=document.createElement("div");row.className="flight-record";const main=document.createElement("div");const route=document.createElement("strong");route.textContent=f.origin+" → "+f.destination;const meta=document.createElement("small");const flightMeta=[f.airline,f.flightNumber].filter(Boolean).join(" · ");meta.textContent=[f.aircraft,flightMeta,new Date(f.date).toLocaleString()].filter(Boolean).join(" · ");main.append(route,meta);const dist=document.createElement("b");dist.textContent=f.km.toLocaleString()+" km · "+f.nm.toLocaleString()+" NM · "+formatFlightTime(Number(f.hours)||estimateFlightHours(f.km,f.aircraft));const del=document.createElement("button");del.type="button";del.textContent="حذف";del.onclick=()=>{const arr=getFlightHistory();arr.splice(arr.length-1-idx,1);localStorage.setItem(flightStoreKey,JSON.stringify(arr));drawFlightHistory()};row.append(main,dist,del);flightHistoryHost.append(row)})}
